/* eslint-disable space-in-parens */

import AccessorArray = require( '@stdlib/array/base/accessor' );
import ghankel = require( './index' );


// TESTS //

// The function returns a collection...
{
	const r = new Float64Array( 3 );
	const c = new Float64Array( 3 );
	const out = new Float64Array( 9 );

	ghankel( 'row-major', 3, 3, r, 1, c, 1, out, 3 ); // $ExpectType Float64Array
	ghankel( 'row-major', 3, 3, new AccessorArray( r ), 1, new AccessorArray( c ), 1, new AccessorArray( out ), 3 ); // $ExpectType AccessorArray<number>
}

// The compiler throws an error if the function is provided a first argument which is not a valid order...
{
	const r = new Float64Array( 3 );
	const c = new Float64Array( 3 );
	const out = new Float64Array( 9 );

	ghankel( 10, 3, 3, r, 1, c, 1, out, 3 ); // $ExpectError
	ghankel( true, 3, 3, r, 1, c, 1, out, 3 ); // $ExpectError
	ghankel( false, 3, 3, r, 1, c, 1, out, 3 ); // $ExpectError
	ghankel( null, 3, 3, r, 1, c, 1, out, 3 ); // $ExpectError
	ghankel( undefined, 3, 3, r, 1, c, 1, out, 3 ); // $ExpectError
	ghankel( [], 3, 3, r, 1, c, 1, out, 3 ); // $ExpectError
	ghankel( {}, 3, 3, r, 1, c, 1, out, 3 ); // $ExpectError
	ghankel( ( x: number ): number => x, 3, 3, r, 1, c, 1, out, 3 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a number...
{
	const r = new Float64Array( 3 );
	const c = new Float64Array( 3 );
	const out = new Float64Array( 9 );

	ghankel( 'row-major', '10', 3, r, 1, c, 1, out, 3 ); // $ExpectError
	ghankel( 'row-major', true, 3, r, 1, c, 1, out, 3 ); // $ExpectError
	ghankel( 'row-major', false, 3, r, 1, c, 1, out, 3 ); // $ExpectError
	ghankel( 'row-major', null, 3, r, 1, c, 1, out, 3 ); // $ExpectError
	ghankel( 'row-major', undefined, 3, r, 1, c, 1, out, 3 ); // $ExpectError
	ghankel( 'row-major', [], 3, r, 1, c, 1, out, 3 ); // $ExpectError
	ghankel( 'row-major', {}, 3, r, 1, c, 1, out, 3 ); // $ExpectError
	ghankel( 'row-major', ( x: number ): number => x, 3, r, 1, c, 1, out, 3 ); // $ExpectError
}

