// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const r = new Float64Array( 3 );
	const c = new Float64Array( 3 );
	const out = new Float64Array( 9 );

	ghankel(); // $ExpectError
	ghankel( 'row-major' ); // $ExpectError
	ghankel( 'row-major', 3 ); // $ExpectError
	ghankel( 'row-major', 3, 3 ); // $ExpectError
	ghankel( 'row-major', 3, 3, r ); // $ExpectError
	ghankel( 'row-major', 3, 3, r, 1 ); // $ExpectError
	ghankel( 'row-major', 3, 3, r, 1, c ); // $ExpectError
	ghankel( 'row-major', 3, 3, r, 1, c, 1 ); // $ExpectError
	ghankel( 'row-major', 3, 3, r, 1, c, 1, out ); // $ExpectError
	ghankel( 'row-major', 3, 3, r, 1, c, 1, out, 3, 10 ); // $ExpectError
}

// Attached to the main export is an `ndarray` method which returns a collection...
{
	const r = new Float64Array( 3 );
	const c = new Float64Array( 3 );
	const out = new Float64Array( 9 );

	ghankel.ndarray( 3, 3, r, 1, 0, c, 1, 0, out, 3, 1, 0 ); // $ExpectType Float64Array
	ghankel.ndarray( 3, 3, new AccessorArray( r ), 1, 0, new AccessorArray( c ), 1, 0, new AccessorArray( out ), 3, 1, 0 ); // $ExpectType AccessorArray<number>
}

